function fitGraph(){const v=$('#graph-viewport');if(v.clientWidth<10||!g.nodes.length)return;const x=Math.min(...g.nodes.map(n=>n.x)),y=Math.min(...g.nodes.map(n=>n.y)),r=Math.max(...g.nodes.map(n=>n.x+244)),b=Math.max(...g.nodes.map(n=>n.y+78+Math.max(DM.NODES[n.type].ins.length,DM.NODES[n.type].outs.length)*32));pan.z=Math.max(.30,Math.min(1.08,(v.clientWidth-60)/(r-x),(v.clientHeight-35)/(b-y)));pan.x=(v.clientWidth-(r-x)*pan.z)/2-x*pan.z;pan.y=(v.clientHeight-(b-y)*pan.z)/2-y*pan.z;applyPan();drawWires();}
