function updatePending(){const h=$('#connect-help');h.classList.toggle('hide',!pendingPin);if(pendingPin){h.textContent='Τώρα πάτησε συμβατή είσοδο. Esc για ακύρωση.';}$$('.pin').forEach(e=>e.classList.toggle('choosing',!!pendingPin&&e.dataset.pinNode===pendingPin.node&&e.dataset.pin===pendingPin.pin&&e.dataset.side===pendingPin.side));}
function connect(a,b){if(a.side==='in'&&b.side==='out')[a,b]=[b,a];if(a.side!=='out'||b.side!=='in'){toast('Χρειάζεσαι μία έξοδο και μία είσοδο, όχι δύο ίδιες πλευρές.',true);return false;}const e=DM.edge(a.node,a.pin,b.node,b.pin),error=DM.validateConnection(g,e);if(error){toast(error,true);addMessage('local',error+'\nΔοκίμασε να ξεχωρίσεις τον τύπο της πληροφορίας από την εκτέλεση.',false);return false;}beforeEdit();g.edges.push(e);pendingPin=null;edited();toast('Σύνδεση έτοιμη. Το αποτέλεσμα θα φανεί όταν εκτελεστεί το γεγονός.');return true;}
function clickPin(el){const p={node:el.dataset.pinNode,pin:el.dataset.pin,side:el.dataset.side};if(pendingPin){if(p.node===pendingPin.node&&p.pin===pendingPin.pin&&p.side===pendingPin.side){pendingPin=null;}else if(connect(pendingPin,p))return;else pendingPin=null;}else pendingPin=p;updatePending();}
