$('#graph-viewport').addEventListener('pointerdown',e=>{if(e.button!==0)return;const pin=e.target.closest('[data-pin]');if(pin){wireDrag={node:pin.dataset.pinNode,pin:pin.dataset.pin,side:pin.dataset.side,x:e.clientX,y:e.clientY};return;}if(e.target.closest('input,button,select,textarea,[data-edge]'))return;const head=e.target.closest('[data-drag-node]');if(head){const n=g.nodes.find(n=>n.id===head.dataset.dragNode);beforeEdit();selectNode(n.id);dragging={type:'node',id:n.id,x:e.clientX,y:e.clientY,ox:n.x,oy:n.y};}else if(e.target.closest('.bpnode')){selectNode(e.target.closest('.bpnode').dataset.node);return;}else{dragging={type:'pan',x:e.clientX,y:e.clientY,ox:pan.x,oy:pan.y};}$('#graph-viewport').setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-dragging.x,dy=e.clientY-dragging.y;if(dragging.type==='node'){const n=g.nodes.find(n=>n.id===dragging.id);n.x=dragging.ox+dx/pan.z;n.y=dragging.oy+dy/pan.z;const el=document.getElementById('node-'+n.id);el.style.left=n.x+'px';el.style.top=n.y+'px';drawWires();}else{pan.x=dragging.ox+dx;pan.y=dragging.oy+dy;applyPan();}});
document.addEventListener('pointerup',e=>{if(wireDrag){if(Math.hypot(e.clientX-wireDrag.x,e.clientY-wireDrag.y)>9){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-pin]');if(target)connect(wireDrag,{node:target.dataset.pinNode,pin:target.dataset.pin,side:target.dataset.side});suppressClick=Date.now()+200;}wireDrag=null;}if(dragging){if(dragging.type==='node')save();dragging=null;}holds.touch=0;$$('[data-hold]').forEach(b=>b.classList.remove('held'));});
