document.addEventListener('click',e=>{if(Date.now()<suppressClick)return;const pin=e.target.closest('[data-pin]');if(pin){clickPin(pin);return;}const a=e.target.closest('[data-action]');if(a){actions[a.dataset.action]?.();return;}const mobile=e.target.closest('button[data-mobile]');if(mobile){setMobile(mobile.dataset.mobile);return;}const tab=e.target.closest('[data-tab]');if(tab){setGuide(tab.dataset.tab);return;}const l=e.target.closest('[data-lesson]');if(l){selectLesson(l.dataset.lesson);return;}const open=e.target.closest('[data-open-lesson]');if(open){closeModal();selectLesson(open.dataset.openLesson);return;}const c=e.target.closest('[data-concept]');if(c){showConcept(c.dataset.concept);return;}const n=e.target.closest('[data-add-node]');if(n){addNode(n.dataset.addNode);return;}const nh=e.target.closest('[data-node-help]');if(nh){const node=g.nodes.find(n=>n.id===nh.dataset.nodeHelp);selectNode(node.id);setGuide('inspect');if(innerWidth<=900){setMobile('guide');setGuide('inspect');}return;}const v=e.target.closest('[data-edit-vector]');if(v){editVector(v.dataset.editVector);return;}const edge=e.target.closest('[data-edge]');if(edge){selected=null;selectedEdge=edge.dataset.edge;$$('.bpnode').forEach(e=>e.classList.remove('selected'));drawWires();return;}const q=e.target.closest('[data-question]');if(q){$('#question').value=q.dataset.question;ask();return;}const anatomy=e.target.closest('[data-anatomy]');if(anatomy){scene.opts.anatomy=anatomy.dataset.anatomy;if(!state.anatomy.includes(anatomy.dataset.anatomy))state.anatomy.push(anatomy.dataset.anatomy);save();evidence();toast(anatomy.dataset.anatomy==='capsule'?'Capsule: σχηματικό περίγραμμα σύγκρουσης, όχι τα ρούχα.':anatomy.dataset.anatomy==='direction'?'Μπροστά για αυτόν τον Actor είναι ο τοπικός +X.':'Mesh: η ορατή φιγούρα. Δεν είναι όλη η κλάση Character.');}if(e.target.id==='overlay')closeModal();});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-value-node]')){const n=g.nodes.find(n=>n.id===el.dataset.valueNode),p=DM.NODES[n.type].ins.find(p=>p.id===el.dataset.valuePin);beforeEdit();if(p.type==='bool')n.values[p.id]=el.checked;else if(p.type==='float'){const v=Number(el.value);if(!Number.isFinite(v)){toast('Χρειάζεται έγκυρος αριθμός.',true);return;}n.values[p.id]=Math.max(-1e5,Math.min(1e5,v));}else n.values[p.id]=el.value.slice(0,1000);edited();}});
