document.addEventListener('keydown',e=>{const typing=e.target.closest('input,textarea,select,[contenteditable=true]');if(e.key==='Escape'){pendingPin=null;updatePending();togglePalette(false);if($('#overlay'))closeModal();return;}if($('#overlay')){if(e.key==='Tab'){const f=$$('.modal button,.modal input,.modal textarea,.modal select,.modal a').filter(x=>!x.disabled);const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(typing)return;if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'){e.preventDefault();undo(e.shiftKey);return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();return;}if(e.code==='KeyW'){e.preventDefault();holds.w=true;}if(e.code==='KeyS'){e.preventDefault();holds.s=true;}if(e.code==='KeyE'&&!e.repeat){e.preventDefault();actions.interact();}});
