$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('Το αρχείο είναι πολύ μεγάλο.');const raw=JSON.parse(await f.text());if(raw.version!==1||!raw.graphs||!DMCourse.lessons.some(l=>l.id===raw.lesson))throw Error('Μη συμβατό αντίγραφο προόδου.');const graphs={};for(const [k,v] of Object.entries(raw.graphs)){if(!DMCourse.lessons.some(l=>l.id===k))continue;graphs[k]=DM.validateGraph(v);}const notes={};for(const [k,v] of Object.entries(raw.notes||{}))if(typeof v==='string')notes[k]=v.slice(0,12000);const progress={};for(const [k,v] of Object.entries(raw.progress||{}))if(['independent','assisted','review','selfreport'].includes(v))progress[k]=v;const imported={version:1,graphs,notes,progress,lesson:raw.lesson,messages:Array.isArray(raw.messages)?raw.messages.filter(m=>m&&typeof m.text==='string'&&['user','local','ai','system'].includes(m.role)).slice(-50).map(m=>({role:m.role,text:m.text.slice(0,16000),time:Number(m.time)||0,concept:DMCourse.concepts[m.concept]?m.concept:null})):[],concepts:{},anatomy:[]};modal('Εισαγωγή προόδου','<p>Το αντίγραφο πέρασε τον έλεγχο μορφής και συνδέσεων. Θα αντικαταστήσει την τοπική πρόοδο αυτής της συσκευής. Κράτησε πρώτα αντίγραφο αν τη χρειάζεσαι.</p>','<button class="btn" data-action="saveexport">Κράτησε τωρινό αντίγραφο</button><button class="btn primary" id="confirm-import">Αντικατάσταση</button>',true);$('#confirm-import').onclick=()=>{stop();state=imported;lesson=DMCourse.lessons.find(l=>l.id===state.lesson);g=state.graphs[lesson.id]||DM.starter(lesson.id);runtime.graph=g;runtime.reset();save();closeModal();renderGraph();route();renderHeader();renderGuide();setTimeout(fitGraph,40);toast('Η πρόοδος εισήχθη.');};}catch(err){toast('Δεν έγινε αλλαγή: '+err.message,true);}e.target.value='';});
$('#image-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>6*1024*1024){toast('Δέχομαι PNG/JPEG/WebP έως 6 MB.',true);return;}try{const img=await createImageBitmap(f),c=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);askedImage=c.toDataURL('image/jpeg',.82);img.close();$('#attachment').innerHTML=esc(f.name)+' · τοπικά, πριν την αποστολή <button id="remove-attachment" aria-label="Αφαίρεση screenshot">✕</button>';$('#remove-attachment').onclick=()=>{askedImage=null;$('#attachment').textContent='';};}catch{toast('Δεν μπόρεσα να ανοίξω την εικόνα.',true);}e.target.value='';});
